fn self_format_comment_block(src: &str, lines: &Lines, block: &[OwnComment], mo: &Options, notes: &mut Vec<Diagnostic>) -> Result<Option<Edit>, Diagnostic> {
    // Determine prefix "#" + optional marker char + space.
    let first = &block[0];
    let prefix = if first.text.starts_with("#' ") || first.text == "#'" {
        "#'".to_string()
    } else {
        "#".to_string()
    };
    let mut content = Vec::new();
    for c in block {
        let t = &c.text;
        if t == &prefix || t.trim_end() == prefix {
            content.push(String::new());
        } else if let Some(r) = t.strip_prefix(&format!("{} ", prefix)) {
            content.push(r.to_string());
        } else {
            return Ok(None);
        }
    }
    let indent = first.indent.clone();
    let width_used = indent.chars().count() + prefix.len() + 1;
    let o = shrink_wrap(mo, width_used);
    let text = content.join("\n");
    let formatted = crate::markdown::format_fragment(&text, &o, notes);
    let mut out = String::new();
    for (k, l) in formatted.iter().enumerate() {
        if k > 0 {
            out.push('\n');
        }
        if l.is_empty() {
            out.push_str(&format!("{}{}", indent, prefix));
        } else {
            out.push_str(&format!("{}{} {}", indent, prefix, l));
        }
    }
    let start = lines.starts[block[0].line];
    let last = block.last().unwrap();
    let end = line_end(src, lines.starts[last.line]);
    Ok(Some(Edit { start, end, text: out }))
}

